head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. gridview_useFilter_WPF-998_(WSQ-2228).xml 실행한다.
    //Run gridview_useFilter_WPF-998_ (WSQ-2228) .xml.
    //Test step 2. name1항목에서 필터링버튼을 클릭하여 전체선택을 체크해제한다.
    //In the name1 field, click the Filter button to uncheck the entire selection.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listRow')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 체크해제시 선택된 데이터가 없어진다.
    //Check and display the selected data.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr:first').css('display') == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr:nth-child(1)').css('display') == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr:nth-child(2)').css('display') == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 33. 필터링버튼을 클릭하여 2건 이상 체크한다.
    //Click on the Filter button to check two or more.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listRow')[2].click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listRow')[3].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_dataLayer').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 2건이상 체크된 상태로 필터링되어진다.
    //Two or more cases are filtered and checked.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr:first').css('display') == 'table-row'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr:nth-child(1)').css('display') == 'table-row'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 다시 필터링 버튼을 클릭한다.
    //Click the Filter Again button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5_filter').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. 정상적으로 필터링 리스트가 보여진다.(이전에는 에러발생하고 필터링 리스트가 보이지 않음)
    //The filtering list is normally displayed (previously an error occurred and the filtering list is not shown).
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_customFilter_scrollView').style.display", "block");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox').get(2).checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox').get(3).checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
